SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args, p.prosrc FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname IN ('is_admin','is_admin_check','has_store_role','has_store_access','has_store_access_as','has_management_access_as','can_manage_store_as','can_read_payroll_store','block_truncate','fin_active_generation','fin_entry_reversal_residual','fin_t12_block_receipt_annulment') ORDER BY p.proname, args;
